# 16x16 pixel-art whistle, drawn here so the art is original and reproducible.
ART = [
    '................',
    '................',
    '..........rr....',
    '.........r..r...',
    '.........r..r...',
    '....oooooo.r....',
    '...oGGGGGGor....',
    '..oGwwGGGGGo....',
    '.oGwGGGGGGGGooo.',
    '.oGGGGkkGGGGGGGo',
    '.oGGGGkkGGGGDDDo',
    '.oGGGGGGGGGDooo.',
    '..oGGGGGGDDo....',
    '...oDDDDDDo.....',
    '....oooooo......',
    '................',
]
COL = {'.': (0, 0, 0, 0), 'o': (74, 46, 10, 255), 'G': (242, 194, 48, 255), 'D': (201, 146, 28, 255),
       'w': (255, 243, 176, 255), 'k': (58, 38, 6, 255), 'r': (216, 64, 47, 255)}
raw = b''.join(b'\x00' + b''.join(bytes(COL[c]) for c in row) for row in ART)


def chunk(tag, data):
    return struct.pack('>I', len(data)) + tag + data + struct.pack('>I', zlib.crc32(tag + data) & 0xffffffff)


png = b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', 16, 16, 8, 6, 0, 0, 0)) + chunk(b'IDAT', zlib.compress(raw, 9)) + chunk(b'IEND', b'')
open(A + '/textures/item/whistle.png', 'wb').write(png)

